code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            rows = [x for x, _ in cells]
            cols = [y for _, y in cells]
            boxes.append((min(rows), max(rows), min(cols), max(cols)))
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            active = False
            for r0, r1, c0, c1 in boxes:
                if r0 <= r <= r1 and c0 <= c <= c1:
                    active = True
                # A marker just outside a rectangle's corner is also part of its pattern.
                if (r in (r0, r1 + 1) and c in (c0 - 1, c1 + 1)) or (r in (r0 - 1, r1) and c in (c0 - 1, c1 + 1)):
                    active = True
                if (r in (r0 - 1, r1 + 1) and c in (c0, c1)):
                    active = True
            if active:
                centers.append((r, c))
    out = [row[:] for row in grid]
    for r, c in centers:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out
'''
